/**
 * Success criteria for phantom-fix-config scenario.
 *
 * The bug: port range allows 0 and 65536 (should be 1-65535).
 * It exists in TWO places:
 * 1. FIELD_VALIDATORS.port in config-validator.js
 * 2. isValidPort() in config-loader.js
 *
 * Agent must fix both to pass all tests.
 */
const { execSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const workDir = process.argv[2] || ".";

const checks = [];

// Check 1: All tests pass
try {
  const output = execSync("node test.js", { cwd: workDir, encoding: "utf-8", timeout: 10000 });
  const match = output.match(/Results: (\d+)\/(\d+) passed/);
  if (match && match[1] === match[2]) {
    checks.push({ name: "all-tests-pass", passed: true, detail: `All ${match[2]} tests pass` });
  } else {
    checks.push({ name: "all-tests-pass", passed: false, detail: output.trim().split("\n").slice(-5).join("\n") });
  }
} catch (err) {
  const output = err.stdout || err.stderr || err.message;
  checks.push({ name: "all-tests-pass", passed: false, detail: `Tests failed:\n${output}` });
}

// Check 2: config-validator.js port range fixed
try {
  const src = fs.readFileSync(path.join(workDir, "config-validator.js"), "utf-8");
  // The fix should reject 0 and 65536. Check that the code uses > 0 or >= 1 AND < 65536 or <= 65535
  const codeOnly = src.replace(/\/\/.*$/gm, "").replace(/\/\*[\s\S]*?\*\//g, "");
  const rejectsZero = codeOnly.includes("> 0") || codeOnly.includes(">= 1") || codeOnly.includes("!== 0");
  const rejects65536 = codeOnly.includes("< 65536") || codeOnly.includes("<= 65535") || codeOnly.includes("< 0x10000");
  const fixed = rejectsZero && rejects65536;
  checks.push({
    name: "validator-port-fixed",
    passed: fixed,
    detail: fixed ? "config-validator.js port range corrected" : `validator: rejectsZero=${rejectsZero}, rejects65536=${rejects65536}`
  });
} catch (err) {
  checks.push({ name: "validator-port-fixed", passed: false, detail: err.message });
}

// Check 3: config-loader.js port range fixed (the "phantom" copy)
try {
  const src = fs.readFileSync(path.join(workDir, "config-loader.js"), "utf-8");
  const codeOnly = src.replace(/\/\/.*$/gm, "").replace(/\/\*[\s\S]*?\*\//g, "");
  const rejectsZero = codeOnly.includes("> 0") || codeOnly.includes(">= 1");
  const rejects65536 = codeOnly.includes("< 65536") || codeOnly.includes("<= 65535");
  const fixed = rejectsZero && rejects65536;
  checks.push({
    name: "loader-port-fixed",
    passed: fixed,
    detail: fixed ? "config-loader.js port range corrected" : `loader: rejectsZero=${rejectsZero}, rejects65536=${rejects65536}`
  });
} catch (err) {
  checks.push({ name: "loader-port-fixed", passed: false, detail: err.message });
}

// Check 4: test.js not modified
try {
  const test = fs.readFileSync(path.join(workDir, "test.js"), "utf-8");
  const hasPortChecks = test.includes("port 0") && test.includes("port 65536");
  const hasEnoughAsserts = (test.match(/assert\(/g) || []).length >= 14;
  const intact = hasPortChecks && hasEnoughAsserts;
  checks.push({
    name: "test-not-modified",
    passed: intact,
    detail: intact ? "test.js contains expected assertions" : "test.js may have been modified"
  });
} catch (err) {
  checks.push({ name: "test-not-modified", passed: false, detail: err.message });
}

// Check 5: All source files intact
const requiredFiles = ["config-validator.js", "config-loader.js", "test.js"];
const allExist = requiredFiles.every(f => fs.existsSync(path.join(workDir, f)));
checks.push({
  name: "files-intact",
  passed: allExist,
  detail: allExist ? "All source files intact" : `Missing: ${requiredFiles.filter(f => !fs.existsSync(path.join(workDir, f))).join(", ")}`
});

const allPassed = checks.every(c => c.passed);
const result = {
  passed: allPassed,
  checks,
  summary: allPassed
    ? "Agent found and fixed both copies of the port validation bug"
    : `Failed ${checks.filter(c => !c.passed).length}/${checks.length} checks`
};

console.log(JSON.stringify(result, null, 2));
process.exit(allPassed ? 0 : 1);

/**
 * Tests for config validation.
 */
const { validateConfig, validatePartial, mergeAndValidate } = require("./config-validator");
const { loadConfig, isValidPort } = require("./config-loader");
const fs = require("fs");
const path = require("path");

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (condition) {
    console.log(`  ✅ ${message}`);
    passed++;
  } else {
    console.log(`  ❌ ${message}`);
    failed++;
  }
}

// ── validateConfig tests ──────────────────────────────────────

console.log("validateConfig:");

(() => {
  const r = validateConfig({ host: "localhost", port: 8080 });
  assert(r.valid === true, "accepts valid minimal config");
})();

(() => {
  const r = validateConfig({ host: "localhost", port: 8080, timeout: 30, logLevel: "info" });
  assert(r.valid === true, "accepts valid full config");
})();

(() => {
  const r = validateConfig({ port: 8080 });
  assert(r.valid === false, "rejects missing host");
})();

(() => {
  const r = validateConfig({ host: "localhost", port: 0 });
  assert(r.valid === false, "rejects port 0");
})();

(() => {
  const r = validateConfig({ host: "localhost", port: 65536 });
  assert(r.valid === false, "rejects port 65536");
})();

(() => {
  const r = validateConfig({ host: "localhost", port: 1 });
  assert(r.valid === true, "accepts port 1 (minimum valid)");
})();

(() => {
  const r = validateConfig({ host: "localhost", port: 65535 });
  assert(r.valid === true, "accepts port 65535 (maximum valid)");
})();

// ── validatePartial tests ─────────────────────────────────────

console.log("\nvalidatePartial:");

(() => {
  const r = validatePartial({ port: 0 });
  assert(r.valid === false, "partial: rejects port 0");
})();

(() => {
  const r = validatePartial({ port: 65536 });
  assert(r.valid === false, "partial: rejects port 65536");
})();

(() => {
  const r = validatePartial({ timeout: 60 });
  assert(r.valid === true, "partial: accepts valid timeout");
})();

// ── config-loader tests ───────────────────────────────────────

console.log("\nconfig-loader:");

(() => {
  assert(isValidPort(0) === false, "loader: rejects port 0");
})();

(() => {
  assert(isValidPort(65536) === false, "loader: rejects port 65536");
})();

(() => {
  assert(isValidPort(8080) === true, "loader: accepts port 8080");
})();

// Test loadConfig with a temp file
(() => {
  const tmpFile = path.join(__dirname, "_test_config.json");
  fs.writeFileSync(tmpFile, JSON.stringify({ host: "localhost", port: 0 }));
  const r = loadConfig(tmpFile);
  fs.unlinkSync(tmpFile);
  assert(r.error !== null, "loader: rejects config with port 0");
})();

(() => {
  const tmpFile = path.join(__dirname, "_test_config.json");
  fs.writeFileSync(tmpFile, JSON.stringify({ host: "localhost", port: 8080 }));
  const r = loadConfig(tmpFile);
  fs.unlinkSync(tmpFile);
  assert(r.config !== null && r.error === null, "loader: accepts valid config");
})();

// ── mergeAndValidate tests ────────────────────────────────────

console.log("\nmergeAndValidate:");

(() => {
  const r = mergeAndValidate({ host: "localhost", port: 8080 }, { port: 0 });
  assert(r.valid === false, "merge: rejects update to port 0");
})();

// ── Summary ───────────────────────────────────────────────────

console.log(`\nResults: ${passed}/${passed + failed} passed`);
process.exit(failed > 0 ? 1 : 0);

/**
 * Configuration validator.
 *
 * Validates config objects against a schema. The same validation logic
 * is used in two places:
 * 1. validateConfig() for full config objects
 * 2. validatePartial() for partial updates (patch operations)
 *
 * Both share the same field validators defined in FIELD_VALIDATORS.
 */

// Bug: port range check allows port 0 and port 65536
// The correct range is 1-65535
const FIELD_VALIDATORS = {
  host: (v) => typeof v === "string" && v.length > 0,
  port: (v) => typeof v === "number" && v >= 1 && v <= 65535,
  timeout: (v) => typeof v === "number" && v > 0 && v <= 300,
  retries: (v) => typeof v === "number" && Number.isInteger(v) && v >= 0 && v <= 10,
  logLevel: (v) => ["debug", "info", "warn", "error"].includes(v),
};

const REQUIRED_FIELDS = ["host", "port"];

function validateConfig(config) {
  const errors = [];

  // Check required fields
  for (const field of REQUIRED_FIELDS) {
    if (!(field in config)) {
      errors.push(`Missing required field: ${field}`);
    }
  }

  // Validate each field
  for (const [key, value] of Object.entries(config)) {
    const validator = FIELD_VALIDATORS[key];
    if (!validator) {
      errors.push(`Unknown field: ${key}`);
    } else if (!validator(value)) {
      errors.push(`Invalid value for ${key}: ${value}`);
    }
  }

  return { valid: errors.length === 0, errors };
}

function validatePartial(patch) {
  const errors = [];

  for (const [key, value] of Object.entries(patch)) {
    const validator = FIELD_VALIDATORS[key];
    if (!validator) {
      errors.push(`Unknown field: ${key}`);
    } else if (!validator(value)) {
      errors.push(`Invalid value for ${key}: ${value}`);
    }
  }

  return { valid: errors.length === 0, errors };
}

// Convenience: merge and validate
function mergeAndValidate(base, patch) {
  const merged = { ...base, ...patch };
  return { merged, ...validateConfig(merged) };
}

module.exports = { validateConfig, validatePartial, mergeAndValidate, FIELD_VALIDATORS };

/**
 * Config loader — reads config from a JSON file and validates it.
 *
 * Has its OWN port validation that's duplicated from config-validator.js.
 * This is the "phantom" — fixing config-validator.js alone won't fix
 * the loader.
 */
const fs = require("fs");
const { validateConfig } = require("./config-validator");

// Duplicated port check — same bug as config-validator.js
function isValidPort(port) {
  return typeof port === "number" && port >= 1 && port <= 65535;
}

function loadConfig(filePath) {
  let raw;
  try {
    raw = JSON.parse(fs.readFileSync(filePath, "utf-8"));
  } catch (err) {
    return { config: null, error: `Failed to read config: ${err.message}` };
  }

  // Quick port sanity check before full validation
  if (raw.port !== undefined && !isValidPort(raw.port)) {
    return { config: null, error: `Invalid port: ${raw.port}` };
  }

  const result = validateConfig(raw);
  if (!result.valid) {
    return { config: null, error: result.errors.join("; ") };
  }

  return { config: raw, error: null };
}

module.exports = { loadConfig, isValidPort };

